from collections import Counter

def func(k, *lists):
    if k <= 0:
        return []
    freq_counter = Counter()
    for lst in lists:
        for num in lst:
            freq_counter[num] += 1
    if not freq_counter:
        return []
    heap = []
    for num, cnt in freq_counter.items():
        if len(heap) < k:
            heapq.heappush(heap, (cnt, num))
        else:
            if cnt > heap[0][0]:
                heapq.heapreplace(heap, (cnt, num))
    result = sorted(heap, key=lambda x: (-x[0], x[1]))
    return [num for cnt, num in result]

