def max_Prime_Factors(n):
    if n <= 1:
        return None
    largest = None
    # handle factor 2
    while n % 2 == 0:
        largest = 2
        n //= 2
    # check odd factors up to sqrt(n)
    f = 3
    while f * f <= n:
        while n % f == 0:
            largest = f
            n //= f
        f += 2
    # if n is still greater than 1, it is a prime factor
    if n > 1:
        largest = n
    return largest

