def counting_sort(arr):
    if not arr:
        return []
    min_val = min(arr)
    max_val = max(arr)
    range_len = max_val - min_val + 1
    count = [0] * range_len
    for num in arr:
        count[num - min_val] += 1
    sorted_arr = []
    for i in range(range_len):
        sorted_arr.extend([i + min_val] * count[i])
    return sorted_arr

