def find_Max_Num(digits):
    # Handle numeric inputs by converting to list of digits
    if isinstance(digits, (int, float)):
        digits = [int(ch) for ch in str(int(digits))]
    else:
        digits = list(digits)
    # Ensure all elements are integers
    digits = [int(d) for d in digits]
    if not digits:
        return 0
    # Sort digits in descending order to form the largest number
    digits.sort(reverse=True)
    # Join and convert back to integer
    return int(''.join(map(str, digits)))

