def max_len_sub(arr):
    n = len(arr)
    if n <= 2:
        return n
    # L[i] maps difference to length of an arithmetic subsequence ending at i
    L = [dict() for _ in range(n)]
    max_len = 2
    # Process from right to left so that L[j] is already computed for j > i
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            diff = arr[j] - arr[i]
            if diff in L[j]:
                L[i][diff] = L[j][diff] + 1
                if L[i][diff] > max_len:
                    max_len = L[i][diff]
            else:
                L[i][diff] = 2
    return max_len

