import re

def multiple_split(string, delimiters=None):
    """

    ----------
    string : str
    delimiters : str, list, tuple or None, optional

    -------
    list
    """
    if delimiters is None:
        pattern = r'\s+'
    elif isinstance(delimiters, (list, tuple)):
        pattern = '|'.join(re.escape(d) for d in delimiters)
    else:
        pattern = delimiters

    if not isinstance(pattern, str):
        raise TypeError("delimiters must be a string, list, tuple, or None")

    return re.split(pattern, string)

