    """
    A pattern is a sequence (list/tuple) that describes a relationship.
    from pattern elements to sequence elements that preserves order.
    """
    def matches(s, p):
        if len(s) != len(p):
            return False
        p_to_s = {}
        s_to_p = {}
        for pat_item, seq_item in zip(p, s):
            if pat_item not in p_to_s:
                if seq_item in s_to_p:
                    return False
                p_to_s[pat_item] = seq_item
                s_to_p[seq_item] = pat_item
            elif p_to_s[pat_item] != seq_item:
                return False
        return True

    # Determine whether `patterns` contains multiple patterns or a single pattern.
    if patterns and isinstance(patterns[0], (list, tuple)):
        # `patterns` is a list of patterns; check against each.
        return any(matches(seq, pat) for pat in patterns)
    else:
        # `patterns` is a single pattern.
        return matches(seq, patterns)

