    """Return the length of the longest word in the given text."""
    if not text:
        return 0
    import string
    translator = str.maketrans('', '', string.punctuation)
    cleaned = text.translate(translator)
    words = cleaned.split()
    if not words:
        return 0
    return max(len(word) for word in words)

