def snake_to_camel(s: str) -> str:
    """
    Convert a snake_case string to camelCase (lower camelCase).
    """
    parts = s.split('_')
    filtered = [p for p in parts if p]
    if not filtered:
        return ''
    return filtered[0].lower() + ''.join(word.capitalize() for word in filtered[1:])

