def eulerian_num(n, m):
    """Return the Eulerian number A(n, m)."""
    if n < 0 or m < 0:
        raise ValueError("n and m must be non‑negative integers")
    if m >= n:
        return 0
    # Dynamic programming using only the previous row.
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        new = [0] * (i + 1)
        for k in range(i):
            new[k] = ((i - k) * dp[k - 1] if k > 0 else 0) + (k + 1) * dp[k]
        dp = new
    return dp[m]

