def merge_sorted_list(*iterables):
    """
    """
    heap = []
    for i, it in enumerate(iterables):
        iterator = iter(it)
        try:
            first = next(iterator)
            heapq.heappush(heap, (first, i, iterator))
        except StopIteration:
            pass
    while heap:
        val, _, iterator = heapq.heappop(heap)
        yield val
        try:
            nxt = next(iterator)
            heapq.heappush(heap, (nxt, _, iterator))
        except StopIteration:
            pass

