def extract_missing(lst, start_range, end_range):
    if start_range > end_range:
        start_range, end_range = end_range, start_range
    intervals = []
    for r in lst:
        if isinstance(r, (list, tuple)) and len(r) == 2:
            s, e = r
            if s > e:
                s, e = e, s
            intervals.append((s, e))
        else:
            intervals.append((r, r))
    intervals.sort(key=lambda x: x[0])
    merged = []
    for s, e in intervals:
        if not merged:
            merged.append([s, e])
        else:
            last = merged[-1]
            if s <= last[1]:
                if e > last[1]:
                    last[1] = e
            else:
                merged.append([s, e])
    missing = []
    if merged:
        if start_range < merged[0][0]:
            missing.append((start_range, merged[0][0]))
        for i in range(len(merged) - 1):
            prev_end = merged[i][1]
            next_start = merged[i+1][0]
            if prev_end < next_start:
                missing.append((prev_end, next_start))
        if merged[-1][1] < end_range:
            missing.append((merged[-1][1], end_range))
    else:
        missing.append((start_range, end_range))
    return missing

