def common_in_nested_lists(*args):
    """
    """
    if not args:
        return []

    def _flatten(lst):
        result = []
        for item in lst:
            if isinstance(item, list):
                result.extend(_flatten(item))
            else:
                result.append(item)
        return result

    # Build a set of elements for each argument
    sets = [set(_flatten(arg)) for arg in args]

    # Intersection of all sets
    common = set.intersection(*sets) if len(sets) > 1 else sets[0]

    return list(common)

