def max_product_tuple(lst):
    """Return the maximum product of the elements of each tuple in lst."""
    if not lst:
        return None
    from functools import reduce
    import operator
    # Compute product for each tuple and keep the max
    max_prod = None
    for t in lst:
        # If a tuple is empty, treat its product as None and skip
        if len(t) == 0:
            continue
        prod = reduce(operator.mul, t)
        if max_prod is None or prod > max_prod:
            max_prod = prod
    return max_prod

