def magic_square_test(square):
    """
    such that every row, column, and both main diagonals sum to the same value.
    """
    # Basic validation: must be a non‑empty list of rows
    if not square or not isinstance(square, (list, tuple)):
        return False

    n = len(square)

    # Ensure every row is a list/tuple of length n
    for row in square:
        if not isinstance(row, (list, tuple)) or len(row) != n:
            return False

    # Flatten the matrix to work with all elements
    flat = [elem for row in square for elem in row]

    # Must contain exactly n*n distinct integers
    if len(flat) != n * n or len(set(flat)) != n * n:
        return False

    # The required sum for each line in an n×n magic square
    target_sum = n * (n * n + 1) // 2

    # Check all rows
    if not all(sum(row) == target_sum for row in square):
        return False

    # Check all columns
    for col in range(n):
        if sum(square[row][col] for row in range(n)) != target_sum:
            return False

    # Check main diagonal (top‑left to bottom‑right)
    if sum(square[i][i] for i in range(n)) != target_sum:
        return False

    # Check anti‑diagonal (top‑right to bottom‑left)
    if sum(square[i][n - 1 - i] for i in range(n)) != target_sum:
        return False

    return True

