def count_samepair(l1, l2, l3):
    """
    Count the number of unordered pairs of indices (i, j) where i < j and
    the elements at those indices are equal across all three input lists.
    """
    if len(l1) != len(l2) or len(l1) != len(l3):
        raise ValueError("All three lists must have the same length.")
    return sum(
        1 for i, j in combinations(range(len(l1)), 2)
        if l1[i] == l1[j] and l2[i] == l2[j] and l3[i] == l3[j]
    )

