def max_path_sum(triangle):
    """Return the maximum total sum from top to bottom of the triangle."""
    if not triangle:
        return 0
    # Start with the bottom row.
    dp = triangle[-1][:]
    # Traverse upwards, updating each element with the best sum reachable from below.
    for i in range(len(triangle) - 2, -1, -1):
        for j in range(i + 1):
            dp[j] = triangle[i][j] + max(dp[j], dp[j + 1])
    return dp[0]

