def parabola_vertex(a, b, c):
    """
    Return the vertex (h, k) of the parabola y = a*x**2 + b*x + c.
    """
    if a == 0:
        raise ValueError("Coefficient 'a' cannot be zero for a parabola.")
    h = -b / (2 * a)
    k = c - (b ** 2) / (4 * a)
    return (h, k)

