def encode_list(lst):
    if not lst:
        return []

    result = []
    current = lst[0]
    count = 1

    for item in lst[1:]:
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1

    result.append((current, count))
    return result

