def solution(a, b, n):
    import math

    # If both coefficients are zero, the equation is either trivially true or impossible.
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None

    g = math.gcd(a, b)
    if n % g != 0:
        return None

    # Extended Euclidean algorithm to find one solution of a*x + b*y = g.
    def egcd(u, v):
        if v == 0:
            return u, 1, 0
        g, x1, y1 = egcd(v, u % v)
        return g, y1, x1 - (u // v) * y1

    _, x0, y0 = egcd(a, b)
    factor = n // g
    return (x0 * factor, y0 * factor)

