def area_polygon(n, side):
    """Return the area of a regular polygon with n sides of length side."""
    if n < 3:
        raise ValueError("Number of sides must be at least 3.")
    if side <= 0:
        raise ValueError("Side length must be positive.")
    # Area formula: A = (n * side^2) / (4 * tan(pi/n))
    return (n * side ** 2) / (4 * math.tan(math.pi / n))

