def sum_of_divisors(n):
    if n <= 0:
        return 0
    total = 0
    sqrt = int(n ** 0.5)
    for i in range(1, sqrt + 1):
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
    return total

def areEquivalent(*numbers):
    if len(numbers) < 2:
        return True
    first_sum = sum_of_divisors(numbers[0])
    return all(sum_of_divisors(num) == first_sum for num in numbers[1:])

