def concatenate_elements(t):
    """Return a tuple with adjacent elements concatenated pairwise."""
    if not t:
        return ()
    result = []
    i = 0
    while i < len(t):
        if i + 1 < len(t):
            a, b = t[i], t[i + 1]
            # If both are strings, use direct concatenation; otherwise convert to string
            if isinstance(a, str) and isinstance(b, str):
                result.append(a + b)
            else:
                result.append(str(a) + str(b))
        else:
            # Odd number of elements: append the last element as a string
            result.append(str(t[i]))
        i += 2
    return tuple(result)

