from collections import Counter

def check_subset_list(subset, superset):
    """
    arbitrarily nested lists. Elements are compared for equality (including
    nesting) and multiplicities are respected.
    """
    def to_hashable(item):
        if isinstance(item, list):
            return tuple(to_hashable(i) for i in item)
        return item

    sub_counter = Counter(to_hashable(elem) for elem in subset)
    super_counter = Counter(to_hashable(elem) for elem in superset)

    for key, count in sub_counter.items():
        if super_counter[key] < count:
            return False
    return True

