def is_majority(arr, elem):
    n = len(arr)
    if n == 0:
        return False

    # Find first occurrence using binary search
    left, right = 0, n - 1
    while left < right:
        mid = (left + right) // 2
        if arr[mid] < elem:
            left = mid + 1
        else:
            right = mid
    first = left if arr[left] == elem else -1
    if first == -1:
        return False

    # Find last occurrence using binary search
    left, right = first, n - 1
    while left < right:
        mid = (left + right) // 2 + 1
        if arr[mid] > elem:
            right = mid - 1
        else:
            left = mid
    last = right

    count = last - first + 1
    return count > n // 2

