def No_of_Triangle(n):
    """Return the maximum number of equilateral triangles that can be formed
    within an equilateral triangle of side length n (in units of the smallest triangles)."""
    if n < 1:
        raise ValueError("n must be a positive integer")
    if n % 2 == 0:
        return n * (n + 2) * (2 * n + 1) // 8
    else:
        return (n * (n + 2) * (2 * n + 1) - 1) // 8

