def check_occurences(records, tolerance=0):
    """Given an iterable of tuples where the first element is a numeric timestamp,
    returns a dict mapping each timestamp (or a bucketed timestamp if tolerance>0)
    to a list of the original tuples that share that timestamp.
    from collections import defaultdict
    grouped = defaultdict(list)
    for rec in records:
        if not isinstance(rec, tuple):
            continue
        time = rec[0]
        if tolerance != 0:
            key = round(time / tolerance) * tolerance
        else:
            key = time
        grouped[key].append(rec)
    return {k: v for k, v in grouped.items() if len(v) > 1}

