def get_total_number_of_sequences(n: int, m: int) -> int:
    if n <= 0 or m <= 0:
        return 0
    if n == 1:
        return m

    # quick check: minimal possible last value is 2^(n-1)
    if m < (1 << (n - 1)):
        return 0

    # prev holds DP for sequences of current length ending at each value 1..m
    prev = [1] * m  # length 1

    for length in range(2, n + 1):
        # prefix sums of prev for O(1) range queries
        prefix = [0] * (m + 1)
        for i in range(m):
            prefix[i + 1] = prefix[i] + prev[i]

        curr = [0] * m
        for i in range(m):
            # value v = i+1, allowed previous values are <= v//2
            max_prev = (i + 1) // 2
            curr[i] = prefix[max_prev]
        prev = curr

    return sum(prev)

