def max_sum(arr):
    """
    """
    n = len(arr)
    if n == 0:
        return 0

    # inc[i] = max sum of increasing subsequence ending at index i
    inc = [0] * n
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # dec[i] = max sum of decreasing subsequence starting at index i
    dec = [0] * n
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Bitonic sum with peak at i is inc[i] + dec[i] - arr[i]
    max_bitonic = 0
    for i in range(n):
        bitonic_sum = inc[i] + dec[i] - arr[i]
        if bitonic_sum > max_bitonic:
            max_bitonic = bitonic_sum

    return max_bitonic

