def division_elements(*tuples):
    if not tuples:
        raise ValueError("At least one tuple must be provided")
    length = len(tuples[0])
    for t in tuples[1:]:
        if len(t) != length:
            raise ValueError("All tuples must have the same length")
    result = []
    for i in range(length):
        value = tuples[0][i]
        for t in tuples[1:]:
            value /= t[i]
        result.append(value)
    return tuple(result)

