def is_num_decagonal(num):
    if num < 1:
        return False
    discriminant = 9 + 16 * num
    sqrt_disc = math.isqrt(discriminant)
    if sqrt_disc * sqrt_disc != discriminant:
        return False
    return (3 + sqrt_disc) % 8 == 0

