def max_sub_array_sum_repeated(nums, k):
    if not nums or k <= 0:
        return 0

    def kadane(arr):
        max_ending = max_sofar = arr[0]
        for num in arr[1:]:
            max_ending = max(num, max_ending + num)
            max_sofar = max(max_sofar, max_ending)
        return max_sofar

    max_single = kadane(nums)
    if k == 1:
        return max_single

    total_sum = sum(nums)

    # max prefix sum (starting at index 0)
    max_prefix = cur = 0
    for num in nums:
        cur += num
        max_prefix = max(max_prefix, cur)

    # max suffix sum (ending at the last index)
    max_suffix = cur = 0
    for num in reversed(nums):
        cur += num
        max_suffix = max(max_suffix, cur)

    if total_sum > 0:
        candidate = max_prefix + (k - 2) * total_sum + max_suffix
        return max(max_single, candidate)
    else:
        return max_single

