def intersection_nested_lists(nested, other):
    """Return a list of elements that appear in both the nested list and the other list.

    nested list that is also present in the other list. Duplicates are kept in the order
    they appear in the nested list.
    """
    def _flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from _flatten(item)
            else:
                yield item

    other_flat = set(_flatten(other))
    return [item for item in _flatten(nested) if item in other_flat]

