def count_Squares(m: int, n: int) -> int:
    """Return the total number of squares (of any size) in an m x n rectangle."""
    if m < 0 or n < 0:
        raise ValueError("Dimensions must be non‑negative integers.")
    total = 0
    min_side = min(m, n)
    for size in range(1, min_side + 1):
        total += (m - size + 1) * (n - size + 1)
    return total

