def find_ways(values, length):
    """Count sequences of the given length whose prefix sums are non‑negative.
    """
    from collections import defaultdict

    # dp[sum] = number of ways to achieve this cumulative sum so far
    dp = {0: 1}
    for _ in range(length):
        next_dp = defaultdict(int)
        for total, ways in dp.items():
            for v in values:
                new_total = total + v
                if new_total >= 0:
                    next_dp[new_total] += ways
        dp = next_dp
    return sum(dp.values())

