def find_rotation_count(arr):
    if not arr:
        return 0
    low, high = 0, len(arr) - 1
    # If the array is not rotated
    if arr[low] <= arr[high]:
        return 0
    while low <= high:
        mid = (low + high) // 2
        # Check if mid is the pivot point (next element is smaller)
        if mid < len(arr) - 1 and arr[mid] > arr[mid + 1]:
            return mid + 1
        # Check if mid - 1 is the pivot point (mid element is smaller than previous)
        if mid > 0 and arr[mid] < arr[mid - 1]:
            return mid
        # Decide which half to search
        if arr[mid] <= arr[high]:
            high = mid - 1
        else:
            low = mid + 1
    return 0

