def even_or_odd(hex_input):
    """

    ----------
    hex_input : str or int
        If str, should be a hexadecimal representation (e.g., '0x1F', '1F').

    -------
    str
        'Even' if the number is even, 'Odd' otherwise.
    """
    try:
        if isinstance(hex_input, str):
            hex_str = hex_input.lower().strip()
            if hex_str.startswith('0x'):
                hex_str = hex_str[2:]
            if not all(c in '0123456789abcdef' for c in hex_str):
                raise ValueError("Invalid hexadecimal string")
            value = int(hex_str, 16)
        elif isinstance(hex_input, int):
            value = hex_input
        else:
            raise TypeError("Input must be a hexadecimal string or an integer")
    except Exception as e:
        raise ValueError(f"Failed to parse input: {e}")

    return "Even" if value % 2 == 0 else "Odd"

