def convert_list_dictionary(*lists):
    if not lists:
        return {}
    if len(lists) == 1:
        return {item: None for item in lists[0]}
    keys_lists = lists[:-1]
    values_list = lists[-1]
    length = len(values_list)
    for kl in keys_lists:
        if len(kl) != length:
            raise ValueError("All input lists must have the same length.")
    result = {}
    for i in range(length):
        path = [kl[i] for kl in keys_lists]
        current = result
        for key in path[:-1]:
