def bitwise_xor(*tuples):
    """

    Args:
        *tuples: One or more tuples of equal length containing integers.

    Returns:
        tuple: A new tuple where each element is the bitwise XOR of the
               corresponding elements from the input tuples.

    Raises:
        ValueError: If the input tuples have different lengths.
    """
    if not tuples:
        return ()

    lengths = [len(t) for t in tuples]
    if len(set(lengths)) > 1:
        raise ValueError("All input tuples must have the same length.")

    result = []
    for group in zip(*tuples):
        xor_val = 0
        for num in group:
            xor_val ^= num
        result.append(xor_val)

    return tuple(result)

