def sumofFactors(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non‑negative")
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                total += i
            j = n // i
            if j != i and j % 2 == 0:
                total += j
        i += 1
    return total

