def find_peak(nums):
    """Return a peak element in the list `nums`."""
    if not nums:
        raise ValueError("find_peak expects a non‑empty list")
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] < nums[mid + 1]:
            left = mid + 1
        else:
            right = mid
    return nums[left]

