def decimal_to_Octal(decimal_num):
    if decimal_num == 0:
        return '0'
    sign = ''
    if decimal_num < 0:
        sign = '-'
        decimal_num = abs(decimal_num)
    oct_digits = []
    while decimal_num > 0:
        oct_digits.append(str(decimal_num % 8))
        decimal_num //= 8
    return sign + ''.join(reversed(oct_digits))

