def max_product(seq):
    """
    (strictly) subsequence of `seq`. If `seq` is empty, return 0.
    """
    if not seq:
        return 0

    n = len(seq)
    # dp[i] holds the maximum product of an increasing subsequence that ends at index i
    dp = seq[:]   # start with the single‑element subsequences
    max_prod = dp[0]

    for i in range(n):
        for j in range(i):
            if seq[j] < seq[i]:
                cand = seq[i] * dp[j]
                if cand > dp[i]:
                    dp[i] = cand
        if dp[i] > max_prod:
            max_prod = dp[i]

    return max_prod

