def separate_paren_groups(paren_string: str) -> List[str]:
    result: List[str] = []
    current: List[str] = []
    depth = 0

    for ch in paren_string:
        if ch == ' ':
            continue
        if ch == '(':
            if depth == 0:
                current = []
            depth += 1
            current.append(ch)
        elif ch == ')':
            depth -= 1
            current.append(ch)
            if depth == 0:
                result.append(''.join(current))
        # ignore any other characters (not expected per spec)

    return result

