from typing import List

def parse_music(music_string: str) -> List[int]:
    """Parse a music string and return a list of beats for each note.

    Supported notes:
    - 'o'   -> whole note (4 beats)
    - 'o|'  -> half note (2 beats)
    - '.|'  -> quarter note (1 beat)
    """
    note_to_beats = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    beats: List[int] = []
    for token in music_string.split():
        if token in note_to_beats:
            beats.append(note_to_beats[token])
        else:
            raise ValueError(f"Unsupported note encountered: '{token}'")
    return beats

