def fib4(n: int):
    """Return the n-th element of the Fib4 sequence."""
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0 or n == 1 or n == 3:
        return 0
    if n == 2:
        return 2
    a, b, c, d = 0, 0, 2, 0
    for _ in range(4, n + 1):
        a, b, c, d = b, c, d, a + b + c + d
    return d

