def is_multiply_prime(a):
    """Return True if `a` is the product of exactly three prime numbers
    (counting multiplicity), otherwise return False. `a` is assumed < 100.
    """
    if a < 2 or a >= 100:
        return False

    factors = []
    d = 2
    while d * d <= a:
        while a % d == 0:
            factors.append(d)
            a //= d
        d += 1
    if a > 1:
        factors.append(a)

    return len(factors) == 3

