def iscube(a):
    sign = 1 if a >= 0 else -1
    x = abs(a)
    # approximate integer cube root of the absolute value
    n = int(round(x ** (1/3)))
    # check a few candidates around the approximation
    for cand in (n - 2, n - 1, n, n + 1, n + 2):
        if sign * cand ** 3 == a:
            return True
    return False

