def decimal_to_binary(decimal):
    """Convert a decimal number to binary, wrapping the result with 'db' at both ends.

    Args:
        decimal: An integer (or value convertible to an integer) representing the decimal number.

    Returns:
    """
    try:
        dec = int(decimal)
    except Exception:
        raise ValueError("Input must be convertible to an integer")
    if dec == 0:
        return "db0db"
    return f"db{bin(dec)[2:]}db"

