def encrypt(s):
    shift = 4
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            # shift within the lowercase alphabet
            new_ch = chr(((ord(ch) - ord('a') + shift) % 26) + ord('a'))
            result.append(new_ch)
        else:
            # leave non‑lowercase characters unchanged
            result.append(ch)
    return ''.join(result)

