def get_odd_collatz(n):
    """
    starting from the positive integer n.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")

    odd_numbers = []
    current = n

    while current != 1:
        if current % 2 == 1:
            odd_numbers.append(current)
        # Compute the next term of the Collatz sequence
        if current % 2 == 0:
            current = current // 2
        else:
            current = 3 * current + 1

    # The sequence always ends with 1, which is odd
    odd_numbers.append(1)

    return sorted(odd_numbers)

