def split_words(txt):
    '''
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    # If any whitespace character is present, split on whitespace
    if any(c.isspace() for c in txt):
        return txt.split()
    # If there is no whitespace but a comma is present, split on commas
    elif ',' in txt:
        return txt.split(',')
    # Otherwise, count lower‑case letters whose order (a=0, b=1, ...) is odd
    else:
        count = 0
        for ch in txt:
            if 'a' <= ch <= 'z':
                if (ord(ch) - ord('a')) % 2 == 1:
                    count += 1
        return count

