def is_sorted(lst):
    if len(lst) <= 1:
        return True
    count = 1
    prev = lst[0]
    for x in lst[1:]:
        if x < prev:
            return False
        if x == prev:
            count += 1
            if count > 2:
                return False
        else:
            count = 1
            prev = x
    return True

