import math

def _is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    limit = int(math.isqrt(n))
    d = 3
    while d <= limit:
        if n % d == 0:
            return False
        d += 2
    return True

def intersection(interval1, interval2):
    start1, end1 = interval1
    start2, end2 = interval2

    lo = max(start1, start2)
    hi = min(end1, end2)

    if hi < lo:
        return "NO"

    length = hi - lo
    return "YES" if _is_prime(length) else "NO"

