def specialFilter(nums):
    """
    and whose first and last digits (ignoring any leading sign) are odd.
    Example:
        specialFilter([15, -73, 14, -15]) => 1
        specialFilter([33, -2, -3, 45, 21, 109]) => 2
    """
    odd_digits = {'1', '3', '5', '7', '9'}
    count = 0
    for n in nums:
        if n <= 10:
            continue
        digits = str(abs(n))
        if digits[0] in odd_digits and digits[-1] in odd_digits:
            count += 1
    return count

